# Build output from nested bounding boxes and reversed layer colors.
R,C=20,19
g=[[0]*C for _ in range(R)]
shapes=[([(1,1,9,10),(3,3,7,8),(4,4,6,7),(5,5,5,6)],[4,1,6,3]), ([(4,13,9,18),(5,14,8,17),(6,15,7,16)],[8,4,5]), ([(11,3,19,15),(12,4,18,14),(13,5,17,13),(14,6,16,12),(15,7,15,11)],[3,4,2,8,6])]
for boxes,colors in shapes:
    for k,(r1,c1,r2,c2) in enumerate(boxes):
        for r in range(r1,r2+1):
            for c in range(c1,c2+1):
                if k==len(boxes)-1 or not (boxes[k+1][0]<=r<=boxes[k+1][2] and boxes[k+1][1]<=c<=boxes[k+1][3]):
                    g[r][c]=colors[k]
for r in g: print(' '.join(map(str,r)))
